}

func buildVarExpr(fields []string)(interface{},error){
 if len(fields)==0 || len(fields)>2 {return nil,trace.BadParameter("variable must have exactly two parts: namespace.name")}
 ns:=fields[0];if ns!="internal"&&ns!="external"&&ns!=LiteralNamespace{return nil,trace.BadParameter("unsupported variable namespace %q",ns)}
