  \"email.local\":func(args ...interface{})(interface{},error){if err:=arity(\"email.local\",args,1);err"'!=nil{return nil,err};e,err:=stringArg(args[0],"email.local");if err!=nil{return nil,err};return EmailLocalExpr{Input:e},nil},
  "regexp.replace":func(args ...interface{})(interface{},error){if err:=arity("regexp.replace",args,3);err!=nil{return nil,err};src,err:=stringArg(args[0],"regexp.replace");if err!=nil{return nil,err};pattern,err:=constantArg(args[1],"regexp.replace pattern");if err!=nil{return nil,err};replacement,err:=constantArg(args[2],"regexp.replace replacement");if err!=nil{return nil,err};re,err:=compileRegexp(pattern);if err!=nil{return nil,err};return RegexpReplaceExpr{Input:src,Pattern:pattern,Replacement:replacement,re:re},nil},
  "regexp.match":func(args ...interface{})(interface{},error){if err:=arity("regexp.match",args,1);err!=nil{return nil,err};pattern,err:=constantArg(args[0],"regexp.match");if err!=nil{return nil,err};re,err:=compileRegexp(pattern);if err!=nil{return nil,err};return RegexpMatchExpr{Pattern:pattern,re:re},nil},
  "regexp.not_match":func(args ...interface{})(interface{},error){if err:=arity("regexp.not_match",args,1);err!=nil{return nil,err};pattern,err:=constantArg(args[0],"regexp.not_match");if err!=nil{return nil,err};re,err:=compileRegexp(pattern);if err!=nil{return nil,err};return RegexpNotMatchExpr{Pattern:pattern,re:re},nil},
 },GetIdentifier:buildVarExpr,GetProperty:buildVarExprFromProperty})
 if err!=nil{return nil,trace.BadParameter("invalid expression %q: %v",exprStr,err)}
 result,err:=p.Parse(exprStr);if err!=nil{return nil,trace.BadParameter("invalid expression %q: %v",exprStr,err)}
 e,ok:=result.(Expr);if !ok{return nil,trace.BadParameter("expected a variable or function expression in %q, got %T",exprStr,result)}
