const (
	LiteralNamespace     = "literal"
	EmailNamespace       = "email"
	EmailLocalFnName     = "local"
	RegexpNamespace      = "regexp"
	RegexpMatchFnName    = "match"
	RegexpNotMatchFnName = "not_match"
	RegexpReplaceFnName  = "replace"
	maxExpressionDepth   = 100
)

// Expression is a string expression with optional surrounding text.
type Expression struct {
	prefix, suffix string
	expr           Expr
}

func (e *Expression) Namespace() string {
	if v, ok := e.expr.(VarExpr); ok {
		return v.Namespace
	}
	if _, ok := e.expr.(StringLitExpr); ok {
		return LiteralNamespace
	}
	return ""
}
func (e *Expression) Name() string {
	if v, ok := e.expr.(VarExpr); ok {
		return v.Name
	}
	if v, ok := e.expr.(StringLitExpr); ok {
		return v.Value
	}
	return ""
}

// Interpolate evaluates an expression using trait values. The optional validator
// is called for every variable, including variables inside nested functions.
func (e *Expression) Interpolate(traits map[string][]string, validators ...func(string, string) error) ([]string, error) {
	ctx := EvaluateContext{VarValue: func(v VarExpr) ([]string, error) {
		if len(validators) > 0 && validators[0] != nil {
			if err := validators[0](v.Namespace, v.Name); err != nil {
				return nil, trace.Wrap(err)
			}
		}
		values, ok := traits[v.Name]
		if !ok {
			return nil, trace.NotFound("variable %s is not found", v.String())
		}
		return values, nil
	}}
	values, err := evalStrings(e.expr, ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	out := make([]string, 0, len(values))
	for _, v := range values {
		if v != "" {
			out = append(out, e.prefix+v+e.suffix)
		}
	}
	if len(out) == 0 {
		return nil, trace.NotFound("variable interpolation result is empty")
	}
	return out, nil
}

// splitTemplate separates one expression from its static surrounding text.
func splitTemplate(input string) (prefix, body, suffix string, templated bool, err error) {
	s := strings.TrimSpace(input)
	start := strings.Index(s, "{{")
	if start < 0 {
		if strings.Contains(s, "}}") || strings.ContainsAny(s, "{}") {
			return "", "", "", false, trace.BadParameter("malformed template usage in %q", input)
		}
		return "", s, "", false, nil
	}
	endRel := strings.Index(s[start+2:], "}}")
	if endRel < 0 {
		return "", "", "", false, trace.BadParameter("malformed template usage in %q", input)
	}
	end := start + 2 + endRel
	prefix, suffix = s[:start], s[end+2:]
	if strings.ContainsAny(prefix+suffix, "{}") || strings.Contains(s[start+2:end], "{{") || strings.Contains(s[start+2:end], "}}") {
		return "", "", "", false, trace.BadParameter("malformed template usage in %q", input)
	}
	body = strings.TrimSpace(s[start+2 : end])
	if body == "" || strings.ContainsAny(body, "{}") {
		return "", "", "", false, trace.BadParameter("malformed template usage in %q", input)
	}
	return prefix, body, suffix, true, nil
}

func NewExpression(input string) (*Expression, error) {
	prefix, body, suffix, templated, err := splitTemplate(input)
	if err != nil {
		return nil, err
	}
	var expr Expr
	if templated {
		expr, err = parse(body)
	} else {
		expr = StringLitExpr{Value: body}
	}
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if expr.Kind() != reflect.String {
		return nil, trace.BadParameter("expression %q must evaluate to a string, got %s", input, expr.Kind())
	}
	return &Expression{prefix: prefix, suffix: suffix, expr: expr}, nil
}

type Matcher interface{ Match(string) bool }
type MatcherFn func(string) bool

func (f MatcherFn) Match(s string) bool { return f(s) }
func NewAnyMatcher(in []string) (Matcher, error) {
	ms := make([]Matcher, len(in))
	for i, s := range in {
		m, err := NewMatcher(s)
		if err != nil {
			return nil, err
		}
		ms[i] = m
	}
	return MatcherFn(func(s string) bool {
		for _, m := range ms {
			if m.Match(s) {
				return true
			}
		}
		return false
	}), nil
}

// MatchExpression evaluates a boolean expression against the text between its prefix and suffix.
type MatchExpression struct {
	Prefix, Suffix string
	Expr           Expr
}

func (m *MatchExpression) Match(in string) bool {
	if !strings.HasPrefix(in, m.Prefix) || !strings.HasSuffix(in, m.Suffix) || len(in) < len(m.Prefix)+len(m.Suffix) {
		return false
	}
	middle := in[len(m.Prefix) : len(in)-len(m.Suffix)]
	v, err := m.Expr.Evaluate(EvaluateContext{MatcherInput: middle})
	return err == nil && v == true
}

func NewMatcher(value string) (Matcher, error) {
	prefix, body, suffix, templated, err := splitTemplate(value)
	if err != nil {
		return nil, err
	}
	var expr Expr
	if templated {
		expr, err = parse(body)
	} else {
		pattern := body
		if !(strings.HasPrefix(body, "^") && strings.HasSuffix(body, "$")) {
			pattern = "^" + utils.GlobToRegexp(body) + "$"
		}
		re, e := compileRegexp(pattern)
		if e != nil {
			return nil, e
		}
		expr = RegexpMatchExpr{Pattern: pattern, re: re}
	}
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if expr.Kind() != reflect.Bool {
		return nil, trace.BadParameter("matcher %q must evaluate to a boolean, got %s", value, expr.Kind())
	}
	return &MatchExpression{Prefix: prefix, Suffix: suffix, Expr: expr}, nil
}

func buildVarExpr(fields []string) (interface{}, error) {
	if len(fields) == 0 || len(fields) > 2 {
		return nil, trace.BadParameter("variable must have exactly two parts: namespace.name")
	}
	ns := fields[0]
	if ns != "internal" && ns != "external" && ns != LiteralNamespace {
		return nil, trace.BadParameter("unsupported variable namespace %q", ns)
	}
	if len(fields) == 1 {
		return VarExpr{Namespace: ns}, nil
	}
	if fields[1] == "" {
		return nil, trace.BadParameter("variable must have exactly two parts: namespace.name")
	}
	return VarExpr{Namespace: ns, Name: fields[1]}, nil
}
