		}
	}
	if e.Kind() != reflect.String {
		return nil, trace.BadParameter("%s requires a string argument, got %s", fn, e.Kind())
	}
	return e, nil
}
func constantArg(a interface{}, fn string) (string, error) {
	s, ok := a.(string)
	if !ok {
		return "", trace.BadParameter("%s requires a constant quoted string argument", fn)
	}
